export class BaseManager{constructor(t={}){this.config={debug:t.debug||!1,performanceTracking:!0,autoInitialize:!0,...t},this.initialized=!1,this.isLoading=!1,this.hasErrors=!1,this.items=new Map,this.metrics={loadTime:0,itemLoadTimes:new Map,itemCount:0,errors:[]},this.events=new Map}async init(t){throw new Error("init() method must be implemented by child class")}set(t,e,s={}){return this.items.set(t,{instance:e,metadata:{added:Date.now(),...s}}),this.metrics.itemCount=this.items.size,this.dispatch("item:added",{name:t,item:e,metadata:s,itemCount:this.items.size}),this.log(`✅ Item added: ${t}`),this}get(t){const e=this.items.get(t);return e?e.instance:null}getWithMetadata(t){return this.items.get(t)}has(t){return this.items.has(t)}async remove(t){const e=this.items.get(t);if(e){if("function"==typeof e.instance.destroy)try{await e.instance.destroy()}catch(e){console.warn(`Error destroying item ${t}:`,e)}return this.items.delete(t),this.metrics.itemCount=this.items.size,this.dispatch("item:removed",{name:t,item:e,itemCount:this.items.size}),this.log(`🗑️ Item removed: ${t}`),!0}return!1}getAll(){const t={};return this.items.forEach((e,s)=>{t[s]=e.instance}),t}getAllWithMetadata(){const t={};return this.items.forEach((e,s)=>{t[s]=e}),t}getNames(){return Array.from(this.items.keys())}getCount(){return this.items.size}updateConfig(t){return Object.assign(this.config,t),this.dispatch("config:updated",{config:this.config}),this}getConfig(){return{...this.config}}getMetrics(){return{...this.metrics,itemCount:this.items.size,initialized:this.initialized,isLoading:this.isLoading,hasErrors:this.hasErrors}}on(t,e){return this.events.has(t)||this.events.set(t,new Set),this.events.get(t).add(e),this}off(t,e){return this.events.has(t)&&this.events.get(t).delete(e),this}dispatch(t,e={}){this.events.has(t)&&this.events.get(t).forEach(s=>{try{s({...e,manager:this,event:t})}catch(e){console.error(`Error in event callback for ${t}:`,e)}});const s=new CustomEvent(`manager:${t}`,{detail:{...e,manager:this},bubbles:!0});return document.dispatchEvent(s),this}log(...t){this.config.debug&&console.log(`[${this.constructor.name}]`,...t)}error(t,e){const s={message:e.message,stack:e.stack,context:t,timestamp:Date.now()};this.metrics.errors.push(s),console.error(`[${this.constructor.name}] Error in ${t}:`,e.message),this.dispatch("error",s),this.hasErrors=!0}handleError(t,e){return this.error(e,t),null}startLoading(){return this.isLoading=!0,this.dispatch("loading:start"),this}stopLoading(){return this.isLoading=!1,this.dispatch("loading:stop"),this}resetMetrics(){return this.metrics={loadTime:0,itemLoadTimes:new Map,itemCount:this.items.size,errors:[]},this}async clear(){const t=Array.from(this.items.keys()).map(t=>this.remove(t));return await Promise.allSettled(t),this.dispatch("cleared"),this}async destroy(){return await this.clear(),this.events.clear(),this.initialized=!1,this.isLoading=!1,this.resetMetrics(),this.dispatch("destroyed"),this.log("Manager destroyed"),this}static isManager(t){return t instanceof BaseManager}}